G_t^\lambda\doteq
(1-\lambda)\sum_{n=1}^{\infty}
\lambda^{n-1}G_{t:t+n}.

G_t^\lambda=
(1-\lambda)\sum_{n=1}^{T-t-1}
\lambda^{n-1}G_{t:t+n}
+\lambda^{T-t-1}G_t.

\begin{aligned}
\mathbf z_{-1}&\doteq\mathbf 0,\\
\mathbf z_t&\doteq\gamma\lambda\mathbf z_{t-1}
+\nabla\hat v(S_t,\mathbf w_t),
\qquad 0\le t\le T.
\end{aligned}

\delta_t\doteq R_{t+1}
+\gamma\hat v(S_{t+1},\mathbf w_t)
-\hat v(S_t,\mathbf w_t).

\overline{\mathrm{VE}}(\mathbf w_\infty)
\le\frac{1-\gamma\lambda}{1-\gamma}
\min_{\mathbf w}\overline{\mathrm{VE}}(\mathbf w).

\delta'_t\doteq R_{t+1}
+\gamma\hat v(S_{t+1},\mathbf w_t)
-\hat v(S_t,\mathbf w_{t-1}).

G_{t:h}^\lambda\doteq
(1-\lambda)\sum_{n=1}^{h-t-1}\lambda^{n-1}G_{t:t+n}
+\lambda^{h-t-1}G_{t:h}.

z_{i,t}\doteq
\begin{cases}
1,&\text{若 }x_{i,t}=1,\\
\gamma\lambda z_{i,t-1},&\text{其他情况。}
\end{cases}

\begin{aligned}
\mathbf w_T
&=\mathbf F_{T-1}(\mathbf F_{T-2}\mathbf w_{T-2}+\alpha G\mathbf x_{T-2})+\alpha G\mathbf x_{T-1}\\
&=\mathbf F_{T-1}\mathbf F_{T-2}\mathbf w_{T-2}
+\alpha G(\mathbf F_{T-1}\mathbf x_{T-2}+\mathbf x_{T-1})\\
&=\mathbf F_{T-1}\mathbf F_{T-2}(\mathbf F_{T-3}\mathbf w_{T-3}+\alpha G\mathbf x_{T-3})
+\alpha G(\mathbf F_{T-1}\mathbf x_{T-2}+\mathbf x_{T-1})\\
&=\mathbf F_{T-1}\mathbf F_{T-2}\mathbf F_{T-3}\mathbf w_{T-3}
+\alpha G(\mathbf F_{T-1}\mathbf F_{T-2}\mathbf x_{T-3}
+\mathbf F_{T-1}\mathbf x_{T-2}+\mathbf x_{T-1})\\
&\vdots\\
&=\underbrace{\mathbf F_{T-1}\mathbf F_{T-2}\cdots\mathbf F_0\mathbf w_0}_{\mathbf a_{T-1}}
+\alpha G\underbrace{\sum_{k=0}^{T-1}\mathbf F_{T-1}\mathbf F_{T-2}\cdots\mathbf F_{k+1}\mathbf x_k}_{\mathbf z_{T-1}}\\
&=\mathbf a_{T-1}+\alpha G\mathbf z_{T-1}.
\end{aligned}

G_{t:t+n}\doteq R_{t+1}+\cdots+\gamma^{n-1}R_{t+n}
+\gamma^n\hat q(S_{t+n},A_{t+n},\mathbf w_{t+n-1}),
\qquad t+n<T,

\begin{aligned}
\mathbf z_{-1}&\doteq\mathbf0,\\
\mathbf z_t&\doteq\gamma\lambda\mathbf z_{t-1}
+\nabla\hat q(S_t,A_t,\mathbf w_t),\qquad 0\le t\le T.
\end{aligned}

\begin{aligned}
G_t
&\doteq R_{t+1}+\gamma_{t+1}G_{t+1}\\
&=R_{t+1}+\gamma_{t+1}R_{t+2}
+\gamma_{t+1}\gamma_{t+2}R_{t+3}
+\gamma_{t+1}\gamma_{t+2}\gamma_{t+3}R_{t+4}+\cdots\\
&=\sum_{k=t}^{\infty}\left(\prod_{i=t+1}^{k}\gamma_i\right)R_{k+1},
\end{aligned}

G_t^{\lambda s}\doteq R_{t+1}
+\gamma_{t+1}\left((1-\lambda_{t+1})\hat v(S_{t+1},\mathbf w_t)
+\lambda_{t+1}G_{t+1}^{\lambda s}\right),

G_t^{\lambda a}\doteq R_{t+1}
+\gamma_{t+1}\left((1-\lambda_{t+1})\hat q(S_{t+1},A_{t+1},\mathbf w_t)
+\lambda_{t+1}G_{t+1}^{\lambda a}\right),

G_t^{\lambda a}\doteq R_{t+1}
+\gamma_{t+1}\left((1-\lambda_{t+1})\bar V_t(S_{t+1})
+\lambda_{t+1}G_{t+1}^{\lambda a}\right),

\begin{aligned}
\mathbf w_{t+1}
&=\mathbf w_t+\alpha\bigl(G_t^{\lambda s}-\hat v(S_t,\mathbf w_t)\bigr)\nabla\hat v(S_t,\mathbf w_t)\\
&\approx\mathbf w_t+\alpha\rho_t\left(\sum_{k=t}^{\infty}\delta_k^s\prod_{i=t+1}^{k}\gamma_i\lambda_i\rho_i\right)\nabla\hat v(S_t,\mathbf w_t).
\end{aligned}

\begin{aligned}
\sum_{t=0}^{\infty}(\mathbf w_{t+1}-\mathbf w_t)
&\approx\sum_{t=0}^{\infty}\sum_{k=t}^{\infty}\alpha\rho_t\delta_k^s\nabla\hat v(S_t,\mathbf w_t)\prod_{i=t+1}^{k}\gamma_i\lambda_i\rho_i\\
&=\sum_{k=0}^{\infty}\sum_{t=0}^{k}\alpha\rho_t\nabla\hat v(S_t,\mathbf w_t)\delta_k^s\prod_{i=t+1}^{k}\gamma_i\lambda_i\rho_i\\
&=\sum_{k=0}^{\infty}\alpha\delta_k^s\sum_{t=0}^{k}\rho_t\nabla\hat v(S_t,\mathbf w_t)\prod_{i=t+1}^{k}\gamma_i\lambda_i\rho_i.
\end{aligned}

\begin{aligned}
G_t^{\lambda a}\doteq{}&R_{t+1}+\gamma_{t+1}\Bigl((1-\lambda_{t+1})\bar V_t(S_{t+1})\\
&\quad+\lambda_{t+1}\bigl[\rho_{t+1}G_{t+1}^{\lambda a}+\bar V_t(S_{t+1})-\rho_{t+1}\hat q(S_{t+1},A_{t+1},\mathbf w_t)\bigr]\Bigr)\\
={}&R_{t+1}+\gamma_{t+1}\Bigl(\bar V_t(S_{t+1})+\lambda_{t+1}\rho_{t+1}\bigl[G_{t+1}^{\lambda a}-\hat q(S_{t+1},A_{t+1},\mathbf w_t)\bigr]\Bigr).
\end{aligned}
